-- Adjuncts only: never a Google task mirror or command queue; no location trail.
CREATE TABLE IF NOT EXISTS family_places (id TEXT PRIMARY KEY, person TEXT NOT NULL CHECK(person IN ('Dani','Cris')), data TEXT NOT NULL CHECK(json_valid(data)), revision INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS family_location_links (id TEXT PRIMARY KEY, person TEXT NOT NULL CHECK(person IN ('Dani','Cris')), place_id TEXT NOT NULL REFERENCES family_places(id), target_key TEXT NOT NULL, data TEXT NOT NULL CHECK(json_valid(data)), revision INTEGER NOT NULL DEFAULT 1, UNIQUE(person,target_key));
CREATE TABLE IF NOT EXISTS family_location_attention (rule_id TEXT PRIMARY KEY REFERENCES family_location_links(id) ON DELETE CASCADE, person TEXT NOT NULL CHECK(person IN ('Dani','Cris')), rule_revision INTEGER NOT NULL, place_revision INTEGER NOT NULL, state TEXT NOT NULL CHECK(state IN ('arrived','nearby','unavailable','outside')), observed_at TEXT NOT NULL, valid_until TEXT NOT NULL);
